import{_ as a,o as n,c as s,a0 as o}from"./chunks/framework.bcCluOOn.js";const w=JSON.parse('{"title":"Workflow Engine","description":"","frontmatter":{},"headers":[],"relativePath":"web/workflow.md","filePath":"web/workflow.md"}'),t={name:"web/workflow.md"};function i(l,e,r,p,c,d){return n(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="workflow-engine" tabindex="-1">Workflow Engine <a class="header-anchor" href="#workflow-engine" aria-label="Permalink to &quot;Workflow Engine&quot;">​</a></h1><p>Modern business applications are rarely just CRUD tables. A <code>Lead</code> becomes an <code>Opportunity</code> and then a <code>Customer</code>. A <code>Prescription</code> gets <code>Prescribed</code> and then <code>Dispensed</code>.</p><p>AAYU ships with a built-in State Machine via the <code>workflow</code> keyword, allowing you to track linear entity lifecycles effortlessly.</p><h2 id="defining-a-workflow" tabindex="-1">Defining a Workflow <a class="header-anchor" href="#defining-a-workflow" aria-label="Permalink to &quot;Defining a Workflow&quot;">​</a></h2><p>You define a workflow by attaching it to an existing <code>entity</code>.</p><div class="language-aayu vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">aayu</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>use workflow.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>entity Order.</span></span>
<span class="line"><span>    text item.</span></span>
<span class="line"><span>end.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>workflow OrderWorkflow for Order.</span></span>
<span class="line"><span>    step Pending.</span></span>
<span class="line"><span>    step Paid.</span></span>
<span class="line"><span>    step Shipped.</span></span>
<span class="line"><span>    step Delivered.</span></span>
<span class="line"><span>end.</span></span></code></pre></div><h2 id="how-it-works-natively" tabindex="-1">How It Works Natively <a class="header-anchor" href="#how-it-works-natively" aria-label="Permalink to &quot;How It Works Natively&quot;">​</a></h2><p>When the AAYU Compiler encounters a <code>workflow</code> block, it automatically:</p><ol><li>Provisions the state graph logic internally.</li><li>Registers a hidden state tracking column to the entity inside SQLite.</li><li>Automatically maps the linear transition constraints so an <code>Order</code> cannot jump directly from <code>Pending</code> to <code>Delivered</code>.</li></ol><p>With just 6 lines of code, you have a mathematically rigorous State Machine integrated into your database.</p>`,10)])])}const f=a(t,[["render",i]]);export{w as __pageData,f as default};
